  // Public Query Methods
  async getUnits() {
    const units = await this.getAllFromStore("units");
    const legacyMap = {
      "1B/1B": "A1 — 675 SF",
      "Studio": "A1 — 675 SF",
      "2B/2B": "B1 — 1,075 SF",
      "3B/2B": "C1 — 1,350 SF",
      "Townhome": "C1 — 1,350 SF"
    };
    const userUnits = [];
    for (const u2 of units) {
      if (isDemoUnit(u2) || DEMO_UNIT_IDS.has(u2.id)) {
        await this.deleteFromStore("units", u2.id);
        this.deleteFromFirestore("units", u2.id).catch(() => {
        });
        continue;
      }
      if (u2.floor_plan && legacyMap[u2.floor_plan]) {
        u2.floor_plan = legacyMap[u2.floor_plan];
        await this.putInStore("units", u2);
        this.pushToFirestore("units", u2.id, u2);
      }
      userUnits.push(u2);
    }
    return userUnits;
  }
